import ezdxf, sys
for path in sys.argv[1:]:
    print("##", path.split("\\")[-1])
    d = ezdxf.readfile(path)
    for e in d.modelspace():
        t = e.dxftype()
        if t == "LINE":
            s, en = e.dxf.start, e.dxf.end
            print(" LINE", e.dxf.layer, round(s.x,2), round(s.y,2), round(en.x,2), round(en.y,2))
        elif t == "ARC":
            c = e.dxf.center
            print(" ARC", e.dxf.layer, round(c.x,2), round(c.y,2), "R", round(e.dxf.radius,2), round(e.dxf.start_angle,1), round(e.dxf.end_angle,1))
        elif t == "CIRCLE":
            c = e.dxf.center
            print(" CIRCLE", e.dxf.layer, round(c.x,2), round(c.y,2), "R", round(e.dxf.radius,2))
        else:
            print(" ", t, e.dxf.layer)

